(()=>{'use strict';const init=()=>{const root=document.querySelector('.rw-tech-console');if(!root)return;const $=id=>root.querySelector('#'+id),rpm=$('rwTechCadence'),res=$('rwTechResistance'),timer=$('rwTechTimer'),toggle=$('rwTechToggle');let seconds=0,interval=null;const render=()=>{$('rwTechRpm').textContent=rpm.value;$('rwTechCadenceValue').textContent=rpm.value+' RPM';$('rwTechResistanceValue').textContent=res.value+' / 15';timer.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')};rpm.addEventListener('input',render);res.addEventListener('input',render);root.querySelectorAll('[data-rw-tech-mode]').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('[data-rw-tech-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('rwTechModeValue').textContent=b.dataset.rwTechMode}));toggle.addEventListener('click',()=>{if(interval){clearInterval(interval);interval=null;toggle.textContent='Resume demo';return}toggle.textContent='Pause demo';interval=setInterval(()=>{seconds++;render()},1000)});$('rwTechReset').addEventListener('click',()=>{if(interval)clearInterval(interval);interval=null;seconds=0;rpm.value=42;res.value=6;root.querySelector('[data-rw-tech-mode="Active"]').click();toggle.textContent='Start demo';render()});render()};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()})();